{
  "verdicts": [
    {
      "candidate_id": "C05",
      "verdict": "true_drift",
      "reason": "httpx has no `Mounts` class; mounts must be passed as a mapping to `Client(mounts=...)`.",
      "code_citation": {
        "path": "httpx/_client.py",
        "start_line": 652,
        "end_line": 652,
        "quote": "mounts: None | (typing.Mapping[str, BaseTransport | None]) = None,"
      },
      "suggested_doc_fix": "Replace `httpx.Mounts({...})` with `mounts = {'http://': HTTPSRedirect(), 'https://': httpx.HTTPTransport()}` and pass it as `httpx.Client(mounts=mounts)`."
    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "other",
      "explanation": "The mounting-transport example uses `httpx.ByteStream`, which is not part of httpx's public API; the available byte-stream types are `SyncByteStream` and `AsyncByteStream`.",
      "doc_citation": {
        "path": "docs/advanced/transports.md",
        "start_line": 291,
        "end_line": 291,
        "quote": "stream = httpx.ByteStream(b\"\")"
      },
      "code_citation": {
        "path": "httpx/_transports/default.py",
        "start_line": 56,
        "end_line": 56,
        "quote": "from .._types import AsyncByteStream, CertTypes, ProxyTypes, SyncByteStream"
      },
      "proposed_fix": "Replace `httpx.ByteStream(b\"\")` with `httpx.SyncByteStream`-compatible streaming, such as a custom synchronous byte stream or `httpx.Response` construction."
    },
    {
      "finding_id": "AD-2",
      "drift_kind": "signature",
      "explanation": "The `HTTPSRedirectTransport` example overrides `handle_request` with an obsolete method signature and tuple return, while the current transport API expects `handle_request(request)` returning an `httpx.Response`.",
      "doc_citation": {
        "path": "docs/advanced/transports.md",
        "start_line": 285,
        "end_line": 285,
        "quote": "def handle_request(self, method, url, headers, stream, extensions):"
      },
      "code_citation": {
        "path": "httpx/_transports/default.py",
        "start_line": 230,
        "end_line": 233,
        "quote": "def handle_request(\n        self,\n        request: Request,\n    ) -> Response:"
      },
      "proposed_fix": "Rewrite the example transport to accept a `request: httpx.Request` in `handle_request` and return an `httpx.Response`, matching the current `BaseTransport` API."
    }
  ]
}
